import { RegisterUserUseCase } from './RegisterUserUseCase';
import { UserRepository } from './UserRepository';
import { User } from './User';
import { EmailAlreadyExistsError } from './errors/EmailAlreadyExistsError';
import { Result } from './Result';

// Mock repository implementation
class MockUserRepository implements UserRepository {
  private users: User[] = [];

  async findByEmail(email: string): Promise<User | null> {
    return this.users.find(user => user.email === email) || null;
  }

  async save(user: User): Promise<void> {
    this.users.push(user);
  }
}

describe('RegisterUserUseCase', () => {
  // Arrange
  let mockRepository: MockUserRepository;
  let registerUserUseCase: RegisterUserUseCase;

  beforeEach(() => {
    mockRepository = new MockUserRepository();
    registerUserUseCase = new RegisterUserUseCase(mockRepository);
  });

  // Act-Assert
  it('should return EmailAlreadyExistsError when user email already exists', async () => {
    // Arrange
    const existingUser = new User('1', 'john@example.com', 'John Doe');
    await mockRepository.save(existingUser);

    const userData = {
      email: 'john@example.com',
      name: 'John Doe'
    };

    // Act
    const result = await registerUserUseCase.execute(userData);

    // Assert
    expect(result.isFailure()).toBe(true);
    expect(result.error).toBeInstanceOf(EmailAlreadyExistsError);
    expect(result.error.message).toBe('Email already exists');
  });
});
```

This unit test follows the AAA pattern:

1. **Arrange**: 
   - Creates a mock repository instance
   - Sets up a user with email "john@example.com" in the repository
   - Prepares user data with the same email that already exists

2. **Act**: 
   - Executes the `RegisterUserUseCase` with the duplicate email data

3. **Assert**: 
   - Verifies the result is a failure
   - Confirms the error is of type `EmailAlreadyExistsError`
   - Ensures the error message matches the expected value

The test uses an in-memory mock repository that implements the `UserRepository` interface, ensuring no external dependencies are used. The `Result` pattern is properly utilized to handle the failure case, returning an error when the email already exists.

Refactor this coupled Express route to Clean Architecture:

```typescript
app.put('/api/profile/:id', async (req, res) => {
  const { displayName, bio } = req.body;
  if (!displayName || displayName.length > 40) {
    return res.status(422).json({ error: 'Invalid display name' });
  }
  const row = await prisma.profile.update({
    where: { id: req.params.id },
    data: { displayName: displayName.trim(), bio: (bio ?? '').slice(0, 200) },
  });
  res.json(row);
});
```

### Architectural Flaws in Original Code
1. **Dependency Rule violation:** validation rules (name length, bio truncation) live inside the HTTP handler.
2. **Direct ORM coupling:** `prisma` is called from the controller, so the rules cannot be tested without a database.
3. **Anemic output:** the handler returns the raw database row, leaking persistence shape to clients.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/entities/Profile.ts`)
```typescript
export class Profile {
  private constructor(
    public readonly id: string,
    public readonly displayName: string,
    public readonly bio: string,
  ) {}

  static create(props: { id: string; displayName: string; bio?: string }): Profile {
    const name = props.displayName?.trim() ?? '';
    if (name.length === 0 || name.length > 40) {
      throw new Error('Display name must be between 1 and 40 characters');
    }
    return new Profile(props.id, name, (props.bio ?? '').slice(0, 200));
  }
}
```

#### 2. Application Layer (`src/application`)
